// Purpose:
// This object checks the click position in the object, converts it to an angle and bends the flexible component to that angle.
// It writes an analog value from 0 to 100, with 0 being no bend and 100 being full bend.  A 90 degree angle is considered a full bend.

var pressedHere = false;

function setup() {
	analogWrite(A0, 0);
	setComponentRotation("flexEnd", 0);
	setDeviceProperty(getName(), "angle", 0);
}

// Purpose:
// Update function.  Put your controls in here.
function mouseEvent(pressed, x, y, firstPress) {
	
	if (firstPress)
		pressedHere = true;
		
	if (pressed && pressedHere) {
		// Calculate the angle between the vectors, one vector made by the touch point and a static vector.
		// For these images 120, 120 is the join point of the two.
		var v1 = {x: 1, y: 0}, v2 = {x: x - 120, y: y - 120};

		var angle = angleAs360(v1.x, v1.y, v2.x, v2.y);
		
		var bend = Math.abs(findAngle(v1.x, v1.y, v2.x, v2.y));
		var percent = bend / 90;
		if(percent > 1)
			percent = 1;

		var result = percent * 100;
		analogWrite(A0, result);
		setComponentRotation("flexEnd", angle);
		setDeviceProperty(getName(), "angle", angle);
		
	} else {
		pressedHere = false;
		analogWrite(A0, 0);
		setComponentRotation("flexEnd", 0);
		setDeviceProperty(getName(), "angle", 0);
	}
	
	
}

// Purpose:
// Takes two vectors and finds the angle between them.  Value is in degrees [-180, 180].
function findAngle(cx, cy, ex, ey)
{
	var dy = ey - cy;
	var dx = ex - cx;
	var theta = Math.atan2(dy, dx);
  	theta *= 180 / Math.PI;
  	return theta;	
}

// Purpose:
// Takes two vectors and finds the angle between them.  Value is in degrees [0, 360].
function angleAs360(cx, cy, ex, ey) 
{
	var theta = findAngle(cx, cy, ex, ey);
	if (theta < 0) 
		theta = 360 + theta;
	
	return theta;
}

